import os,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
gi,go=G['Demo pair 1 input'],G['Demo pair 1 output']

def f(grid):
    h,w=len(grid),len(grid[0])
    out=[[0]*w for _ in range(h)]
    colors={v for row in grid for v in row if v}
    for c in colors:
        cells=[(i,j) for i,row in enumerate(grid) for j,v in enumerate(row) if v==c]
        top=min(i for i,j in cells); left=min(j for i,j in cells)
        for i,j in cells:
            out[i-top][j]=c
    return out
print(f(gi)==go)

o=f(gi)
for r1,r2 in zip(o,go):
    print(''.join(map(str,r1)), '|', ''.join(map(str,r2)))
